const WryError = require('../wryError');

module.exports = function (wry, wryPackageModule, extensions) {
  extensions = extensions || wryPackageModule.getExtensionsList().map(extension => {
    try {
      return wryPackageModule.require(extension);
    }
    catch (ex) {
      throw new WryError(`Unable to load extension \`${extension}\``, { innerError: ex });
    }
  });

  for (const plugin of extensions) {
    wry.plugin(plugin);
  }

  return wry;
};